   "question": "实际上雾霾形成的原因是多方面的，识别污染源是有效治理大气污染至关重要的环节。对京津冀区域而言，认清区域内污染源的共性及差别，有助于区域内地区________地对污染源进行综合治理。\n填入画横线部分最恰当的一项是：",
