   "source": "2016年国家公务员录用考试《行测》题（副省级） · 第9题",
   "question": "改进作风涉及习俗、文化、制度、利益等方方面面，本身就是一场攻坚战。无论是克服            的形式主义、官僚主义，还是打破思维定势、疗治沉疴顽疾，都需要有坚韧不拔的毅力。只有这样，才能            ，积小胜为大胜，取得让广大干部群众满意的成效。\n依次填入画横线部分最恰当的一项是：",
