   "question": "没有互联网的时候，商家跟消费者之间的交易以信息不对称为基础，       地讲，就是“买的不如卖的精”。但有了互联网，消费者掌握的信息越来越多，于是变得越来越精明，越来越具有       。如果你的产品或服务做得好，好得超出他们的预期，即使一分钱广告不投，消费者也愿意在网上分享，       为你树口碑。 \n依次填入画横线部分最恰当的一项是：",
