   "question": "图书出版人首先应是一个文化人，然后才是一个生意人。只有在这两者之间求得一种       的平衡，才能在这个日益萎缩的图书市场中生存下去。用这个标准来衡量，有些出版人就不太合格：要么过于看重文化的附加值，对市场化的道路       ；要么把图书看作一单单生意，只顾着炮制各种       的畅销书。  \n依次填入画横线部分最恰当的一项是：",
