   "question": "随着债务置换计划的实施，地方债到期不能偿付的风险基本消弭，刚性兑付再一次得到确保。但地方债管理要真正走向规范化，还有许多技术问题有待解决，其中最为突出的就是地方政府的信用评级问题。信用评级是债券定价的基础，直接关乎发行方的融资成本，但由于信用评级标准不明确，东部发达地区和西部欠发达地区的政府信用评级―样，地方政府信用和国家信用评级一样，甚至还出现地方债利率低于国债利率的情形，这在理论上显然是说不通的，也完全不能反映“市场在资源配置中起决定性作用”的要求。\n这段文字意在强调：",
