   "module": "言语理解与表达",
   "source": "2017年国家公务员录用考试《行测》题（地市级） · 第21题",
   "question": "继指纹识别、虹膜识别等身份认证技术出现之后，科学家们正在研究耳道识别技术。这种识别技术以微型入耳式耳塞为载体，耳机发出的声波进入外耳道的鼓膜，到中耳、内耳，再反射回鼓膜，形成的声学共振频谱在人与人之间具有个体差异，可以通过样本匹配并判断使用者的身份，这种识别技术是基于耳道孔构造的唯一性，识别时间仅需1秒，准确率达到99%。\n关于耳道识别技术，这段文字没有涉及：",
