   "source": "2017年国家公务员录用考试《行测》题（地市级） · 第23题",
   "question": "许多度假胜地，例如鼎鼎大名的夏威夷，完全是由火山喷发的熔岩堆积形成的，直到今天，夏威夷火山群的面积还在不断扩大。岩浆中含有大量微量元素，风化之后形成的土壤异常肥沃，造福了当地的百姓。火山岩干净且透水，火山区的水质一流，是众多天然矿泉水基地。此外，火山区还蕴藏着大量矿产，比如黄金、钻石等。在科学上，火山还是研究板块构造很好的载体，它是板块漂移学说最有力的证据之一。\n这段文字主要介绍：",
   "options": [
    "A. 夏威夷成为旅游胜地的原因",
    "B. 火山的经济、生活与科学价值",
    "C. 板块漂移学说的研究思路",
    "D. 火山岩与土壤、水质的关系"
   ],
   "answer": "B",
   "analysis": "文段首先指出许多度假胜地是由火山喷发形成，并举了夏威夷的例子，接下来指出火山为当地的百姓提供肥沃的土壤和天然矿泉水，即阐述火山的生活价值，“此外”之后指出火山区蕴含矿产，即阐述火山的经济价值，尾句阐述火山的科学价值。文段重点阐述火山在经济、生活和科学三个方面的价值，对文段归纳概括，对应B项。\nA项，“夏威夷”为举例论证的表述，非重点，排除；\nC项，“板块漂移学说”对应尾句表述，表述片面，且非文段谈论的重点内容，排除；\nD项，对应“此外”之前的内容，表述片面，排除。\n故正确答案为B。\n【文段出处】《火山喷发的影响》",
   "exam": "guokao",
   "year": 2017
