   "question": "从医学角度看，非酒精性脂肪肝是因为脂代谢紊乱等多种因素引起了肝细胞内中性脂肪（主要是甘油三酯和脂肪酸）过度堆积。脂代谢紊乱引发的多种重要组织损伤，特别是心脑血管和肝脏损害，对健康造成极大威胁，因此其机制和防治策略研究一直是国际上医学研究的前沿领域。专家指出，尽管饮食控制和改变生活方式对高脂血症及脂肪肝有明显的改善作用，但在现实生活中很难实施，患者往往由于各种因素不能严格执行医嘱。到目前为止，人类尚未研发出可以根治和阻止肝脏脂代谢紊乱的有效药物。\n关于脂代谢紊乱，文中没有提及：",
