   "question": "绿叶蔬菜中的硝酸盐被人体摄入后，一部分不吸收而被大肠细菌利用，最终排出体外；另一部分被吸收，在几个小时当中逐渐缓慢转变成微量的亚硝酸盐。亚硝酸盐的存在时间只有几分钟，然后转变成一氧化氮，发挥扩张血管的作用。换句话说，如果需要亚硝酸盐扩张血管的作用，完全用不着吃剩菜；而且一次性大量摄入亚硝酸盐是有害的，摄入硝酸盐之后，在体内缓慢转变成亚硝酸盐，才能发挥有益作用。\n这段文字反驳了哪种观点？",
