   "answer": "B",
   "analysis": "给出文字开头出现“由此可见”，引出服饰出现流行缘由的这一结论，故前文应具体表述导致服饰出现的原因，尾句由“通过&#39;冠&#39;的形制，我们可以更好地理解这一点”可知，后文应具体论述“&#39;冠&#39;的形制”，对应文段，第②段具体表述了政治的规定导致了“进贤冠”服饰的出现，第③段具体阐述了“冠冕的形制”，题干文段在②③段间可起到承上启下的作用，衔接恰当，B项当选。\n①段通过“鹖冠”进行话题引入，④段由“冠冕形制的复杂，却还不是极限”可知，此段承接③段仍在论述冠冕的形制，⑤段在论述重视冠冕的原因，均与题干话题衔接不当，排除A、C、D三项。\n故正确答案为B。\n【文段出处】《冠冕何以堂皇》",
