   "question": "地球并非太阳系唯一有水的星球，木卫二所拥有的水资源就比地球还多，堪称一颗            的“水球”。不过，与其邻居木卫三相比，木卫二就             了。通过研究木卫三上极光的微小偏移，科学家推断木卫三拥有巨大的地下海洋，液态水的含量可能是地球的30倍。\n依次填入画横线部分最恰当的一项是：",
