   "source": "2020年国家公务员录用考试《行测》题（地市级） · 第12题",
   "question": "商品或服务没有质量的保障，就像生命失去了健康一样，一切都                。人们进行网络消费时，能够一眼看到价格，却很难发现是否存在质量问题。这种情况下，质量因素便更加关键。如果商家在营销环节耍小聪明，以低价为噱头，轻视质量，就如同                ，等到“东窗事发”，注定会收到消费者的差评。\n依次填入画横线部分最恰当的一项是：",
   "options": [
    "A. 无从谈起  掩耳盗铃",
    "B. 无济于事  饮鸩止渴",
    "C. 徒劳无功  作茧自缚",
    "D. 黯然失色  买椟还珠"
   ],
