   "analysis": "第一空，根据“当今世界正经历百年未有之大变局，新一轮科技革命和产业变革深入发展”可知，横线处应体现在这样的背景下，国际力量对比有了深刻的变化，A项“调整”指改变原有的情况，C项“变化”指事物在形态上或本质上产生新的状况，均符合文意，保留。B项“扭转”指使事物的发展方向或目前的状况发生变化，侧重大的变化，与“深刻”搭配不当，排除；D项“变换”指事物的一种形式或内容换成另一种，文段只是表达力量对比发生变化，而非变成另一种东西，排除。\n第二空，根据“和平与发展仍然是时代主题”可知，横线处应体现人类命运共同体理念是人们所推崇的，A项“深入人心”指理论、学说、政策等为人们深切了解和信服，符合文意，当选。C项“源远流长”形容历史悠久，文段未体现人类命运共同体理念时间悠久，排除。\n故正确答案为A。\n【文段出处】《深刻认识和把握新发展阶段的五个维度》",
   "exam": "guokao",
