   "source": "2022年国家公务员录用考试《行测》题（副省级） · 第19题",
   "question": "人体肠道内生物的多样性令人惊讶，除细菌外，还        着数十万种被称为噬菌体的病毒，这些噬菌体可以感染细菌。众所周知，肠道微生物组不平衡会引发各种疾病，如炎症性肠病、过敏和肥胖，但我们对肠道细菌及噬菌体在人类健康和疾病方面起何种作用却            。\n依次填入画横线部分最恰当的一项是：",
   "options": [
    "A. 潜伏 知之甚少",
    "B. 分布 浑然不觉",
    "C. 活跃 束手无策",
    "D. 充斥 一知半解"
   ],
   "answer": "A",
   "analysis": "第一空，所填词语搭配“病毒”，表示人体肠道内存在病毒。A项“潜伏”、B项“分布”、C项“活跃”用在此处均可，保留。D项“充斥”指充满、多得到处都是，正常的人体不可能体内到处都是病毒，用在此处程度过重，排除。\n第二空，横线前出现“但”“却”表示转折，根据前文“众所周知”可知，转折前表示人们对肠道微生物了解的足够多，故所填成语表示人们对肠道细菌及噬菌体的作用了解的少。A项“知之甚少”指对某方面知道的太少，符合文意，当选。B项“浑然不觉”指毫无察觉，文段讨论的是人们对微生物的具体作用是否了解，而非是否察觉其作用，排除；C项“束手无策”形容遇到问题时毫无解决的办法，文段并非强调没有解决办法而是知道的少，排除。\n故正确答案为A。\n【文段出处】《人肠道内竟有超14万种病毒，其中一半以上从未见过》",
   "exam": "guokao",
   "year": 2022,
   "materialId": "xzm-93cygy-2"
