   "question": "系统观念是做好“十四五”时期各项工作必须坚持的重要原则。各级税务机关要加强          思考，立足当前、放眼长远，加强税收领域前沿问题研究，增强做好税收工作的主动性和预见性。要进行          谋划，自觉把税收工作融入到党和国家事业发展大局中去思考和谋划，加强“十四五”税收改革发展的顶层设计。\n依次填入画横线部分最恰当的一项是：",
