   "source": "2022年国家公务员录用考试《行测》题（副省级） · 第25题",
   "question": "发达国家一两百年出现的环境问题，在我国30多年来的快速发展中集中显现，呈现明显的结构型、压缩型、复合型特点，老的环境问题尚未解决，新的环境问题            。走老路，去无节制消耗资源，去不计代价污染环境，            ！要正确处理经济发展同生态环境保护之间的关系，更加        地推动绿色发展、循环发展、低碳发展，决不以牺牲环境、浪费资源为代价换取一时的经济增长。\n依次填入画横线部分最恰当的一项是：",
