   "module": "言语理解与表达",
   "source": "2022年国家公务员录用考试《行测》题（副省级） · 第26题",
   "question": "？这是党史观的重大问题。一个马克思主义政党对自己的错误所抱的态度，是衡量这个党是否真正履行对人民群众所负责任的一个最重要最可靠的尺度。我们党对自己包括领袖人物的失误和错误历来采取郑重的态度，一是敢于承认，二是正确分析，三是坚决纠正，从而使失误和错误连同党的成功经验一起成为宝贵的历史教材。\n填入画横线部分最恰当的一项是：",
   "options": [
    "A. 如何对待逆耳忠言",
    "B. 如何看待曲折、失误",
    "C. 是否始终坚持实事求是",
    "D. 犯了错误后能否正确应对"
   ],
   "answer": "B",
   "analysis": "横线出现在开头，需结合后文内容进行分析。根据“这是党史观的重大问题”可知，横线处需填入一个表示“问题”的句子，后文先通过“最重要”“最可靠”两个程度词强调“马克思主义政党”面对自己错误的态度很重要。接着详细解释了我们党在面对失误和错误时采取的态度，并强调这种态度取得了较好的效果。故后文重在强调我们党在面对失误和错误时所采取的态度，则横线处所填问题应该与面对错误的态度有关，B项“曲折、失误”即政党发展过程中的问题、错误，符合文意，当选。\nA项，“逆耳忠言”强调建议、忠告，偏离后文核心话题“面对错误的态度”，排除；\nC项，“实事求是”与后文“问题”“态度”无关，话题不一致，无中生有，排除；\nD项，“能否正确应对”为对策表述，后文强调面对错误时应有的态度，而非如何应对错误，排除。\n故正确答案为B。\n【文段出处】《旗帜鲜明坚持和运用正确党史观》",
