   "source": "2022年国家公务员录用考试《行测》题（副省级） · 第31题",
   "question": "①海绵是一种最原始的多细胞动物，化石记录最早可追溯到寒武纪时期，至今已发展到一万多种\n②阿糖腺苷成为首个从海洋天然产物衍生并成功上市的抗病毒药物\n③目前，从海绵提取物中分离得到的天然产物往往具有独特的结构骨架或显著的生理功能，可用于开发药物和作为有机合成或半合成化学中间体，具有作为药物先导物的巨大潜力\n④日本化学家从日本黑海绵中提取了软海绵素，将其衍生成抗肿瘤药物，用于治疗转移性乳腺癌等癌症\n⑤作为一种营固着生长的生物体，海绵极易被其他生物猎食，却能在残酷的海洋环境中生存，可能依赖于其独特的化学防御策略\n⑥美国化学家从海绵中分离得到抗病毒药阿糖腺苷和抗癌药物阿糖胞苷的先导化合物\n将以上6个句子重新排列，语序正确的一项是：",
   "options": [
    "A. ①⑤③⑥②④",
    "B. ①③④②⑥⑤",
    "C. ⑤①④⑥②③",
    "D. ⑤③①④②⑥"
   ],
   "answer": "A",
   "analysis": "对比选项，确定首句。①句是对海绵下定义，⑤句是在介绍海绵能够在残酷的海洋环境中生存，应先引出海绵再介绍其生存，故①句更适合作首句，排除C、D两项。\n继续观察，②⑥两句均提及信息“阿糖腺苷”，②句介绍阿糖腺苷成功上市，⑥句指出美国化学家从海绵中分离出阿糖腺苷，按照逻辑顺序应先引出阿糖腺苷，然后再介绍其成功上市，故⑥句应在②句之前，排除B项。\n故正确答案为A。\n【文段出处】《从海洋放线菌天然宝库中“淘金”》",
