   "module": "言语理解与表达",
   "source": "2022年国家公务员录用考试《行测》题（副省级） · 第33题",
   "question": "福厦高铁是我国第一条真正意义上的海洋环境下运行的高速铁路。湄洲湾跨海大桥是其中最长的海域施工区段，也是全线的重点控制性工程，其主桥设计为预应力混凝土连续刚构矮塔斜拉桥。索鞍是斜拉桥施工中的关键环节，施工精度高，控制难度大。湄洲湾跨海大桥位于曲线段上，海域风大浪急，斜拉桥主塔索鞍定位困难。为达到主跨通航要求，主墩承台均需埋入河床面以下，这给围堰施工作业增加了难度。施工人员克服海上恶劣天气的影响，采取预埋劲性骨架、增加控制点位等手段实现了索鞍精确定位，有效地解决了索鞍定位控制难题。\n这段文字主要介绍了湄洲湾跨海大桥：",
   "options": [
    "A. 对福厦高铁贯通的重要意义",
    "B. 围堰施工中面临的复杂环境",
    "C. 索鞍定位的难点及解决措施",
    "D. 使用矮塔斜拉索结构的原因"
   ],
   "answer": "C",
   "analysis": "文段开篇通过福厦高铁引出湄洲湾跨海大桥，接着又通过其斜拉桥引出“索鞍”话题，提出索鞍施工精度高，控制难度大，并重点指出由于湄洲湾跨海大桥位于曲线段且海上风浪大，“索鞍”定位困难，最后提到施工人员克服困难，采取了一系列措施实现了索鞍的精确定位。故文段核心话题为“索鞍”，主要介绍了索鞍在定位中遇到的一系列难点问题及解决措施，对应C项。\nA项，“福厦高铁”对应文段首句引出话题部分，非重点，且未提到核心话题“索鞍”，排除；\nB项，未提到文段核心话题“索鞍”，且“复杂环境”只涉及问题部分，排除；\nD项，文段并未论述要应用矮塔斜拉索结构的原因，无中生有，且未提到核心话题“索鞍”，排除。\n故正确答案为C。\n【文段出处】《这条跨海高铁创多项“中国造”之最》",
   "exam": "guokao",
   "year": 2022,
   "materialId": "xzm-93cygy-2"
