   "module": "言语理解与表达",
   "source": "2022年国家公务员录用考试《行测》题（地市级） · 第23题",
   "question": "长期以来，人民调解员队伍以兼职为主。兼职人民调解员的优势是容易发挥基层社会各行各业的力量，国家投入人力成本和财政成本比较低。但同时，由于兼职调解员在时间精力、专业素质等方面受限，制约了调解工作的有效开展。在现阶段，一方面，矛盾纠纷主体更加多元、类型更加多样，调解难度不断加大；另一方面，人民群众的权利意识、法治意识不断增强，对矛盾纠纷化解质效提出了更高要求。这些都需要人民调解员投入更多的时间和精力，具备较高的政策水平、法律素养和专业知识。\n这段文字接下来最可能说的是：",
   "options": [
    "A. 兼职人民调解员的局限性",
    "B. 人民调解制度的发展过程",
    "C. 人民调解员应当具备的专业素养",
    "D. 建立人民调解员专职队伍的举措"
   ],
   "answer": "D",
   "analysis": "文段开篇介绍背景，指出人民调解员队伍以兼职为主，接着介绍了兼职人民调解员的优势，然后通过转折词“但”指出问题，接着指出现阶段矛盾调解难度大且要求更高，这些需要人民调解员投入更多时间和精力，并具备更高的政策水平、法律素养和专业知识，即兼职人民调解员已不能够解决所有纠纷问题，需要更加专业的团队。故后文应围绕解决兼职人民调解员所存在的问题，建立人民调解员专职队伍展开，对应D项。\nA项，“兼职人民调解员的局限性”前文已经论述，接下来不会继续论述，排除；\nB项，“人民调解制度”文段并未提及，衔接不当，排除；\nC项，“专业素养”对应“法律素养”，仅为尾句的其中一部分对策，表述片面，排除。\n故正确答案为D。\n【文段出处】《用法理情守护千家万户的安宁祥和》",
   "exam": "guokao",
   "year": 2022
