   "analysis": "首先，根据选项判断首句，③句指出日前科研人员发现了叩甲总科的新科；④句介绍了叩甲总科是最多见的生物发光的昆虫物种类群，按照逻辑顺序，应先介绍叩甲总科，再介绍叩甲总科的新科，故④句在③句前，排除A、B两项。\n继续观察，发现⑥句出现指代词“这一新类群”，说明前句应该提出了新类群相关的概念，⑥句前有②句、③句，②句在介绍生物发光的叩甲总科物种的种属关系，只有③句介绍了“新类群”，故③⑥两句捆绑，排除D项，C项当选。\n故正确答案为C。\n【文段出处】《1亿年前萤火虫就已学会发光抵御捕食者》",
   "exam": "guokao",
