   "question": "近年来出现的《我在故宫修文物》等以国宝为题材的纪录片，提供了认识历史的新        。这些纪录片以具体的文物为线索，又不        于文物，而是描绘物品所处时代的精神世界，以此引导当代观众与传统文化发生碰撞，引导情感参与，开拓历史视野。这些节目如同荧屏上的博物馆，让观众            。\n依次填入画横线部分最恰当的一项是：",
