   "module": "言语理解与表达",
   "source": "2023年国家公务员录用考试《行测》题（副省级） · 第12题",
   "question": "人造血即血氧液，能够用来代替人类血液，满足临床需求，缓解血液短缺状况。而且人造血标准化的生产流程能够确保其          ，输入人造血不用再担心会感染艾滋病、肝炎等疾病，可最大程度降低输血相关传染病的风险。因此，研制和批量生产人造血成为当前的热点。\n填入画横线部分最恰当的一项是：",
   "options": [
    "A. 安全性",
    "B. 可靠性",
    "C. 规范性",
    "D. 稳定性"
   ],
