   "source": "2023年国家公务员录用考试《行测》题（副省级） · 第21题",
   "question": "各种舰载机的搭配协同，防空、反舰、反潜力量的集成以及编队舰艇的配合，使得以航母为中心的海上编队战斗力惊人。因此，航母的            备受关注。在拥有持续高航速的情况下，航母可以            地快速部署到位，突如其来地发动攻击，或在对方发起攻击之前驶离对方的打击范围。\n依次填入画横线部分最恰当的一项是：",
   "options": [
    "A. 风吹草动 猝不及防",
    "B. 蛛丝马迹 不声不响",
    "C. 出没隐现 不期而至",
    "D. 一举一动 出其不意"
   ],
   "answer": "D",
   "analysis": "本题可从第二空入手，根据“突如其来地发动攻击，或在对方发起攻击之前驶离对方的打击范围”可知，横线处成语应体现突然、让人无法预料到之意。D项“出其不意”指趁对方没有料到就采取行动，符合文意，保留。A项“猝不及防”指事情突然发生，来不及防备，常见用法为“让人猝不及防”“令人猝不及防”，置于此处用法不当，排除；B项“不声不响”指不说话，不出声，C项“不期而至”指没有预料地到来，侧重于没有约定而到来，均无法体现“突然、让人无法预料到”之意，排除。\n第一空，代入验证。D项“一举一动”指人的所有活动，置于此处形容航母的每一次活动，符合文意，当选。\n故正确答案为D。\n【文段出处】光明网《航母：跑得越快越好》",
   "exam": "guokao",
   "year": 2023,
   "materialId": "xzm-9a3i1t-2"
