   "source": "2023年国家公务员录用考试《行测》题（地市级） · 第2题",
   "question": "“报得准”是气象监测预报预警的生命力。天气预报准确率高，防灾减灾才能            ，为有关部门正确决策提供科学客观的支撑，应急处置才能有力有效。\n填入画横线部分最恰当的一项是：",
