   "question": "我国十四亿多人口整体迈向现代化社会，规模超过现有发达国家人口的总和，艰巨性和复杂性            ，发展途径和推进方式也必然具有自己的特点。我们始终从国情出发想问题、作决策、办事情，既不好高骛远，也不因循守旧，保持历史        ，坚持稳中求进、循序渐进、持续推进。\n依次填入画横线部分最恰当的一项是：",
