   "question": "要加强国际传播的理论研究，掌握国际传播的规律，构建对外话语体系，提高传播艺术。要采用        不同区域、不同国家、不同群体受众的精准传播方式，推进中国故事和中国声音的全球化表达、区域化表达、分众化表达，增强国际传播的          和实效性。\n依次填入画横线部分最恰当的一项是：",
