   "question": "竞争与创新总是            。平台反垄断最终要在抑制垄断与鼓励创新之间达到平衡。一方面，要加快健全市场准入制度、公平竞争审查机制，预防和        滥用行政权力限制竞争，充分        市场竞争机制的强大动能；另一方面，要引导和激励平台企业把更多精力用在创新上。唯有如此，平台经济方能为全社会注入持久的创新活力。\n依次填入画横线部分最恰当的一项是：",
