   "question": "“反觇”思维是从事物甲和乙之间的联系，反推出乙同甲的另一种联系的方法。在作战指挥中，敢于“反道而觇之”，往往能跳出局部观全局、打破常规辟蹊径。面对复杂多变的战场形势，指挥员若能换位于敌、        定式，从侧面甚至反向来决策，及时        行动部署，就会拥有战场制敌的更大胜算。\n依次填入画横线部分最恰当的一项是：",
