   "question": "世界航天大国都在积极开展空间碎片清除技术研究，提出了各自的清除方案。总的来看有两大类：一类是接触式，如机械臂抓捕、安装离轨装置等；第二类是非接触式，如用激光或离子束等进行推移。两类清除方式            ，都是要让碎片离开当前轨道，进入大气层烧毁。\n填入画横线部分最恰当的一项是：",
   "options": [
    "A. 如出一辙",
    "B. 殊途同归",
    "C. 双管齐下",
    "D. 各有千秋"
   ],
   "answer": "B",
   "analysis": "横线前介绍了两种不同的空间碎片清除方案，横线后介绍两类清除方式都是让碎片离开当前轨道并进入大气层烧毁，即最后实现的目标一致，故横线处表达虽然方法不同但最终实现的目标相同。B项“殊途同归”比喻采取不同的方法而得到相同的结果，符合文意，当选。\nA项“如出一辙”指好像出自同一车辙，形容两种事物非常相似，侧重强调两种清除方式“相似”，与文意不符，排除；C项“双管齐下”比喻从两方面同时进行，D项“各有千秋”指各有所长，各有优点，各有特色，与B项相比，均无法体现文段中得到了相同结果这一含义，与文意不符，排除。\n故正确答案为B。\n【文段出处】人民网《太空也需要“清道夫”（科技大观）》",
   "exam": "guokao",
   "year": 2024,
