   "module": "言语理解与表达",
   "source": "2024年国家公务员录用考试《行测》题（副省级） · 第13题",
   "question": "全面从严治党和鼓励担当作为是内在统一的，不是彼此对立的。严并不是要把大家管死，使人瞻前顾后、畏首畏尾，搞成暮气沉沉、            的一潭死水，而是要通过明方向、          、正风气、强免疫，形成风清气正的党内政治生态，营造有利于干事创业的良好环境，进一步调动全党的积极性、主动性、创造性。\n依次填入画横线部分最恰当的一项是：",
   "options": [
    "A. 浑浑噩噩 讲原则",
    "B. 唯唯诺诺 严法纪",
    "C. 无所事事 守底线",
    "D. 无所作为 立规矩"
   ],
   "answer": "D",
   "analysis": "第一空，搭配“一潭死水”，且根据“鼓励担当作为”可知，横线处表明“从严治党”让一些人害怕被问责而“不敢作为”，从而使党内成了一潭死水，故横线处应体现“不作为”之意，C项“无所事事”指闲着什么事都不干，D项“无所作为”指工作中安于现状，缺乏创造性，均与“一潭死水”搭配恰当，且符合文意，保留。A项“浑浑噩噩”形容糊里糊涂，愚昧无知，B项“唯唯诺诺”形容自己没有主意，一味附和，恭顺听从的样子，均与“不作为”无关，排除。\n第二空，根据横线前后可知，横线处与“明方向、正风气、强免疫”形成并列，即明确方向、肃正风气、强化免疫，此三者均为我党在从严治党过程中作为发出动作的主体所发挥的重要作用，D项“立规矩”意为确立规矩，符合文意，构成并列，当选。C项“守底线”意为守住底线，应为广大党员作为被治理的客体，在工作中必须做到的，与其他三项的并列不及D项准确，排除。\n故正确答案为D。\n【文段出处】《全面贯彻党的二十大精神的科学指引》光明网",
