   "source": "2024年国家公务员录用考试《行测》题（副省级） · 第14题",
   "question": "发展社会主义协商民主，要把民主集中制的优势运用好，发扬“团结——批评——团结”的优良传统，广开言路，            ，促进不同思想观点的充分表达和深入交流，做到相互尊重、平等协商而不强加于人，遵循规则、有序协商而不各说各话，体谅包容、真诚协商而不偏激偏执，形成既畅所欲言、            ，又理性有度、合法依章的良好协商氛围。\n依次填入画横线部分最恰当的一项是:",
   "options": [
    "A. 集思广益 各抒己见",
    "B. 不耻下问 百家争鸣",
    "C. 兼收并蓄 取长补短",
    "D. 虚怀若谷 从善如流"
   ],
   "answer": "A",
   "analysis": "第一空，根据“，”可知，横线处与“广开言路”构成并列，语义相近，“广开言路”指尽可能地让人们广泛发表意见，故横线处也应体现此意，A项“集思广益”指集中群众的智慧，广泛吸收有益的意见，符合文意，保留。B项“不耻下问”指不以向地位比自己低、知识比自己少的人请教为可耻，与文意不符，排除；C项“兼收并蓄”指把不同内容、不同性质的东西收下来，保存起来，并不强调让人们广泛发表意见，与文意不符，排除；D项“虚怀若谷”指胸怀像山谷那样深且宽广，形容十分谦虚，与文意不符，排除。\n第二空，代入验证，根据“、”可知，横线处与“畅所欲言”构成并列，语义相近，“畅所欲言”指尽情地说出想说的话，没有约束地把心里话吐露出来，A项“各抒己见”指各自发表自己的意见或见解，符合文意，当选。\n故正确答案为A。\n【文段出处】人民日报《把协商民主贯穿履行职能全过程》",
