   "question": "许多老大难问题之所以长期无解，重要原因是调查研究流于形式，导致情况吃得不透、病根找得不准。有的是“盲人摸象”式调研，眼中只有一个个孤立的“盆景”，得出的结论往往是            ；有的是“刻舟求剑”式调研，对新情况多凭主观判断下结论，导致出台的政策          不强。\n依次填入画横线部分最恰当的一项是：",
   "options": [
    "A. 以偏概全 针对性",
    "B. 老生常谈 科学性",
    "C. 一孔之见 时效性",
    "D. 闭门造车 可行性"
   ],
   "answer": "A",
   "analysis": "第一空，根据“有的是‘盲人摸象’式调研，眼中只有一个个孤立的‘盆景’”可知，横线处应体现“盲人摸象”式调研得出的结论，“盲人摸象”比喻对事物了解不全面，以偏概全，乱加揣测。A项“以偏概全”指片面地根据局部现象来推论整体，得出错误的结论，C项“一孔之见”比喻狭隘片面的见解，均符合文意，保留。B项“老生常谈”指人们听惯了的没有新意的话，D项“闭门造车”比喻只凭主观办事，不顾客观实际，均与文意不符，排除。\n第二空，根据横线前“导致”可知，横线处应体现“刻舟求剑”式调研所带来的结果，即死守教条，拘泥成法，固执不变通，出台的政策无法解决眼下的问题。A项“针对性”指对确定的对象采取具体措施，置于此处可体现出台的政策没有从客观实际出发，精准性不强之意，当选。C项“时效性”指同一件事物在不同的时间具有很大的性质上的差异，侧重强调时间的重要性，文段并未体现出台的政策过时、落伍，与文意不符，排除。\n故正确答案为A。\n【文段出处】《调查研究要戒“虚”存“真”》",
   "exam": "guokao",
   "year": 2024,
   "materialId": "xzm-9gu1mo-2"
