   "question": "“潜”是“显”的基础，“显”是“潜”的结果。对于事关长远、事关基础的任务，“一口吃不成个胖子”，就要扎扎实实、稳步有序推进。这些工作并不            ，政绩也并非            ，但有助于各项事业全面发展、长足进步，是真正对党、对人民、对历史负责的体现。\n依次填入画横线部分最恰当的一项是：",
