   "question": "年轻干部要提高抓落实能力。干事业不能做样子，必须脚踏实地，抓工作落实要以上率下、            。特别是主要领导干部，既要带领大家一起定好盘子、理清路子、开对方子，又要做到重要任务亲自部署、关键环节亲自把关、落实情况亲自督查，不能高高在上、            ，不能只挂帅不出征。干事业就要有钉钉子精神，抓铁有痕、踏石留印，            向前走，过了一山再登一峰，跨过一沟再越一壑，不断通过化解难题开创工作新局面。\n依次填入画横线部分最恰当的一项是：",
