   "question": "生命科学界普遍认同“科学数据共享”，研究人员在使用数据库的同时，将自己研究发现的基因序列或蛋白质结构数据存入数据库，同时成为数据库的使用者和          。如今，数据库已经成为生命史书最        的纪录载体和强大的数据分析平台，为整个生命科学研究所        。\n依次填入画横线部分最恰当的一项是：",
