   "source": "2024年国家公务员录用考试《行测》题（副省级） · 第34题",
   "question": "。我们党当初为什么要创办中央党校？就是为人民解放事业培养骨干力量。90年来，各级党校特别是中央党校与党的事业同频共振、按需施训，教育培训了一批又一批领导干部，肩负起为党育才的神圣职责，推动党的事业从胜利走向新的胜利。例如，党校创办初期，马克思共产主义学校一年多时间里共培训了 1000 多名干部；延安时期，中央党校常规班次培养各类骨干上万人，其中约 65%的七大代表有中央党校的学习工作经历。党的十八大以来，中央党校举办的主体班次共培训轮训干部8.8万人，其中省部级干部1.3万余人。\n填入画横线部分最恰当的一项是：",
   "options": [
    "A. 党校是领导干部锤炼党性的“大熔炉 ”",
    "B. 党校是干部教育培训的主阵地",
    "C. 党校是传承党的精神血脉的殿堂",
    "D. 党校是党的意识形态工作的重要前沿阵地"
   ],
   "answer": "B",
   "analysis": "横线出现在文段开头，需结合后文内容进行分析。横线后首先提出“我们党当初为什么要创办中央党校”的问题，接着回答问题，即“培养骨干力量”，之后指出多年来中央党校通过教育培训领导干部推动党的事业从胜利走向新的胜利，接下来通过“例如”进行举例论证，阐述在不同时期中央党校具体培训的干部数据。故后文主要强调在中央党校进行了大量干部教育培训，真正做到了为党育才，B项“主阵地”一词形象而准确，当选。\nA项，“党性”指党的本质属性，是通过政党的纲领、章程、思想基础、奋斗目标、根本制度等表现出来，反推后文应围绕深入开展理想信念、党的宗旨、革命传统等党性教育培训展开论述，而文段强调在中央党校进行干部教育培训，没有提到关于“锤炼党性”的培训内容，与文意不符，排除；\nC项“传承党的精神血脉”、D项“党的意识形态工作”文段均未提及，无中生有，且偏离文段核心话题 “干部”，排除。\n故正确答案为B。\n【文段出处】中共中央党校《在中央党校建校90周年庆祝大会暨2023年春季学期开学典礼上的讲话》",
   "exam": "guokao",
   "year": 2024,
   "materialId": "xzm-9gu1mo-2"
