   "source": "2024年国家公务员录用考试《行测》题（副省级） · 第36题",
   "question": "①当前，我国荒漠化、沙化土地治理呈现出“整体好转、改善加速”的良好态势，但沙化土地面积大、分布广、程度重、治理难的基本面尚未根本改变\n②现实表明，我国荒漠化防治和防沙治沙工作形势依然严峻\n③我国是世界上荒漠化最严重的国家之一，荒漠化土地主要分布在三北地区，而且荒漠化地区与经济欠发达区、少数民族聚居区等高度耦合\n④荒漠化、风沙危害和水土流失导致的生态灾害，制约着三北地区经济社会发展，对中华民族的生存、发展构成挑战\n⑤我们要充分认识防沙治沙工作的长期性、艰巨性、反复性和不确定性，进一步提高站位，增强使命感和紧迫感\n⑥这两年，受气候变化异常影响，我国北方沙尘天气次数有所增加\n将以上6个句子重新排列，语序正确的一项是：",
   "options": [
    "A. ①③⑥⑤②④",
    "B. ②⑤⑥①④③",
    "C. ④①③②⑥⑤",
    "D. ③④①⑥②⑤"
   ],
   "answer": "D",
   "analysis": "对比选项，确定首句。①句和②句均介绍我国的荒漠化、沙化土地的防治情况。③句介绍我国是荒漠化最严重的国家之一及我国荒漠化土地的主要分布地区，引出我国“荒漠化”这一话题。根据逻辑顺序，应先引出“荒漠化”的话题，再论述其防治的情况，故③句应在①句和②句之前，锁定D项。\n验证D项的逻辑，③句引出“我国是荒漠化最严重的国家之一”这一话题，接着④句介绍荒漠化影响着生态及经济等的发展，随后①句介绍荒漠化经过治理虽有好转，但根本问题依然存在，⑥句通过近两年我国北方沙尘天气次数增加对前文进行论证，接着通过②句再次指出我国的荒漠化及沙化防治形势严峻，最后⑤句给出对策，我们要认识到防沙治沙工作的特性，提高站位，增强使命感和紧迫感，逻辑通顺，当选。\n故正确答案为D。\n【文段出处】国家林业和草原局《习近平在内蒙古巴彦淖尔考察并主持召开加强荒漠化综合防治和推进“三北”等重点生态工程建设座谈会》",
