   "question": "战场上未解之惑、未识之物、未通之理皆可疑。战场中的善疑并非一味多疑或疑而无度，而是要从全局出发，围绕作战目的、作战对手、作战体系而“疑”，观察战场态势，分析关联要点，力求对敌方的军事行动            ，对敌方的结构体系心知肚明，从而把握重心，掌握大局。\n填入画横线部分最恰当的一项是（  ）",
