   "question": "量子理论描述了微观粒子的诸多反直觉行为，广义相对论描述了引力的本质，并做出许多        的预言，比如黑洞、引力波、引力透镜等。这两种理论在各自领域都运作得非常好，却无法以一种        的方式结合起来。因此，寻找能将这两种理论统一起来的量子引力理论，是物理学家最大的        之一。\n依次填入画横线部分最恰当的一项是：",
