   "question": "读书学习的过程，实际上是一个不断思考认知的过程。思考是阅读的        ，是认知的必然，是把书读活的关键。如果只是机械地阅读、被动地接受、        地浏览，没有思考，            ，再好的知识也难以吸收和消化。\n依次填入画横线部分最恰当的一项是：",
