   "source": "2024年国家公务员录用考试《行测》题（地市级） · 第20题",
   "question": "守正是创新的前提，创新是守正的路径。守正不是            、循规蹈矩，而是守住本和源、根和魂；创新也不是凭空幻想、            ，而是在把握事物发展规律的基础上充分发挥主观能动性。只有守正，才能恪守正道、            ；只有创新，才能与时俱进、推陈出新。\n依次填入画横线部分最恰当的一项是：",
