   "question": "个人信息保护案件往往涉及非法收集、获取、提供、出售、购买、使用个人信息等多个环节，责任主体除了已被追究刑事责任的犯罪者外，还可能包括下游的违法处理信息者。在民事公益诉讼案件办理中，是否可以连带追究下游违法者的赔偿责任，司法实践中存在争议。根据民法典，认定连带责任必须遵循法定或约定原则，在此原则指导下，个人信息保护法规定了共同处理者的连带责任。因此，当不同侵权主体主观具有共同过错，客观上实施了共同侵害个人信息权益的行为时，可以依法追究各侵权人的连带责任。\n关于个人信息保护案件，作者认为：",
