   "source": "2025年国家公务员录用考试《行测》题（副省级） · 第13题",
   "question": "要提高“临事能断”本领，就要处理好反复权衡与适时决断的关系，既要深入考量、三思而行，又要视情而断、当机立断，不能等待观望、            、议而不决。当然，提倡在关键时刻善于决断，并不意味着可以            、我行我素，而是要善于聚民意、集众智，推动科学决策。\n依次填入画横线部分最恰当的一项是：",
   "options": [
    "A. 犹豫不决 泥古不化",
    "B. 左顾右盼 听之任之",
    "C. 举棋不定 刚愎自用",
    "D. 见风使舵 自作主张"
   ],
   "answer": "C",
   "analysis": "第一空，顿号引导并列关系，故横线处所填词语应与“等待观望”“议而不决”语义相近，体现不能决断之意。A项“犹豫不决”指拿不定主意，B项“左顾右盼”指向左边看看，又向右边看看，形容顾虑重重、犹豫不决的样子，C项“举棋不定”比喻犹豫不决，拿不定主意，三项均符合文意，保留。D项“见风使舵”比喻看势头或看别人的眼色行事，无法体现不能决断之意，排除。\n第二空，顿号引导并列关系，横线处所填词语应与“我行我素”语义相近，体现不管别人意见，按照自己想法去做之意。C项“刚愎自用”指十分倔强固执，不考虑别人的意见，符合文意，当选。A项“泥古不化”指拘泥于古代的成规或古人的说法而不知变通，与文意无关，排除。B项“听之任之”指听任事情自然发展变化，不管不问，强调放任自流的消极态度，无法表达完全按照自己想法去做之意，排除。\n故正确答案为C。\n【文段出处】解放军报《锤炼“临事能断”本领》",
   "exam": "guokao",
