   "question": "无论采取哪种储存方式，液氢对储存系统          的要求都比传统燃油系统更高、更复杂。这是因为氢分子远小于航空煤油，更容易从管路缝隙中        ；对于液氢储存，还必须考虑        条件的实现问题，否则升温气化后体积膨胀的氢气有可能导致燃料箱因压强骤增而直接爆炸。\n依次填入画横线部分最恰当的一项是：",
