   "id": "xz-1wepc2w",
   "module": "言语理解与表达",
   "source": "2025年国家公务员录用考试《行测》题（副省级） · 第19题",
   "question": "改进文风就要多写“短实新”的好文章。“实”就是讲符合实际的话不讲脱离实际的话，讲管用的话不讲空话，讲反映自己思考的话不讲            的话，讲有感而发的话不讲            的话，讲通俗明白的话不讲故作高深的话，            ，用朴实的语言阐述深刻的理论。\n依次填入画横线部分最恰当的一项是：",
