   "source": "2025年国家公务员录用考试《行测》题（地市级） · 第2题",
   "question": "《营造法式》刊行之后，两浙一带的建筑技术借助官方的推广完全融入了中国古典木构建筑技术的主流。以抬梁式为梁柱结构，屋面重量通过椽、檩、梁、斗栱、柱传递至基础的方案，形成此后中国官式建筑            的发展路径。这种结构开间大，立柱少，气势恢宏，可细分为殿堂式与厅堂式，满足不同礼制等级的需要。\n填入画横线部分最恰当的一项是：",
   "options": [
    "A. 源远流长",
    "B. 标新立异",
    "C. 一枝独秀",
    "D. 一以贯之"
   ],
   "answer": "D",
   "analysis": "横线处所填词语搭配“发展路径”。根据“完全融入了中国古典木构建筑技术的主流······形成此后中国官式建筑······的发展路径”可知，横线处应体现此后中国官式建筑按照这一路径继续发展之意。D项“一以贯之”指用一种思想理论贯穿于始终，置于此处可体现发展路径一直延续之意，符合文意，当选。A项“源远流长”比喻历史悠久，根底深厚，常搭配“历史”，与“发展路径”搭配不当，排除。B项“标新立异”多形容敢于改革创新或提出新奇的主张，表示与一般不同，也指为了显示自己而故意另搞一套，文段既未体现“创新”，也未体现“故意另搞一套”，不符合文意，排除。C项“一枝独秀”形容在同类人或同类事物中出类拔萃，文段并未体现“出类拔萃”之意，不符合文意，排除。\n故正确答案为D。\n【文段出处】吴文化博物馆《百工有业｜从紫禁之巅到纽约苏园——从古代走入现代的香山帮》",
   "exam": "guokao",
