   "question": "在青藏高原高寒草甸的多年冻土区，地下水或土壤水分迁移冻结导致地下冰聚集，使地表隆起形成的丘状地带便是冻胀丘。冻胀丘中土壤结构和植物根系的破坏，改变了地表径流，导致部分缓坡和低地积水严重，继而引起草地破碎化和地表裸露区增加等草地荒漠化问题。随着冻土内冰的消融和水分流出，地下有时会形成较大的空洞区，地表发生沉降和塌陷，往往会造成地区植被和土壤的显著退化。冻土区随着表层冻土的解冻融化，坡体中的饱水松散土层和风化层间的摩擦力减小，在重力作用下，沿斜坡缓慢流动或蠕动形成融冻泥流，这也会使植被和土壤遭到强烈破坏。\n这段文字接下来最可能介绍青藏高原：",
   "options": [
    "A. 冻胀丘对高原生态系统的危害",
    "B. 地表植被的恶劣生存状况",
    "C. 多年冻土区的形成原因",
    "D. 冻土所致荒漠化的防治措施"
   ],
