   "question": "相较于地球，月球上氦-3储量极为丰富。氦-3来源于太阳内部核聚变，以高能粒子形式通过太阳风向宇宙扩散。月球没有大气层，其磁场不足地球的千分之一，使得太阳风能够直射月球表面并将氦-3注入月壤层。同时，月表温度在月夜最低可达img/formula-97d25d12075b7ed0.webp，极地永久阴影区甚至可达img/formula-8c540cbbedab0e09.webp。极低温环境有效促进了氦-3被月壤层吸附，阻止其向太空逃逸，并在月表不断富集。据估算，全月氦-3换算储量高达110万吨，可作为清洁核原料供地球使用约1万年。\n这段文字能够解释下列哪一问题？",
