   "question": "政府机关作为法律授权履行公共职责的部门，承担广告监管职责            ，但网络平台企业也应参与网络广告的治理。法律规定，互联网平台经营者在提供互联网信息服务过程中应当采取措施防范、制止违法广告，将网络平台视为违法广告的“          ”，要求其扮演“协同监管者”的角色。\n依次填入画横线部分最恰当的一项是：",
