   "analysis": "第一空，根据“再严明的纪律，不执行、不遵守、不维护”及“纪律不是可松可紧的橡皮筋，不是可有可无的空摆设”可知，横线处所填成语应体现纪律在没有落实的情况下无法发挥效用之意。B项“徒劳无功”指白白付出劳动而没有成效，C项“一纸空文”指只是写在纸上没有兑现或不能兑现的东西，D项“虚有其表”指空有好看的外表，实际上不行，指有名无实，三项均能体现出纪律如果不被执行、遵守、维护，就成了毫无意义的规定，符合文意，保留。A项“事与愿违”指事情的发展与主观愿望相反，侧重结果与期望不符，横线处强调纪律不被执行、遵守、维护就形同虚设，并非强调结果与期望的关系，与文意不符，排除。\n第二空，通过“更”可知，横线处与“不认真学习造成的情况”构成递进关系，前后语义相近，程度加重。C项“明知故犯”指明明知道不能做，却故意违犯，可与前文构成递进关系，且符合文意，保留。B项“混淆是非”指故意把正确的说成错误的，把错误的说成正确的，与“不认真学习党纪党规”语义不相近，排除。D项“有恃无恐”指因有所倚仗而毫不害怕，文段并未提及“倚仗”，与文意不符，排除。\n第三空，代入验证。根据“有的把政治规矩置于脑后”“毫无自我约束”可知，横线处所填成语应体现对党的纪律要求不当回事。C项“束之高阁”的意思是把东西捆起来，放在高高的架子上，指弃置不用或置之不理，符合文意，当选。\n故正确答案为C。\n【文段出处】新华网《从严抓好党的纪律建设》",
