   "question": "从本质上看，量子雷达成像的原理与传统雷达一致，都是对电磁场携带信息的提取，但二者获取物体信息的物理机制不同。传统成像技术建立在电磁场的确定性理论模型之上，利用电磁场的一阶关联信息，通过记录辐射场的光强或相位分布获取物体的图像信息；而量子成像技术则建立在电磁场的量子统计不确定性理论之上，利用了电磁场的高阶关联信息，通过辐射场分布的强度、相位的空间统计特性获得物体图像信息，因而量子雷达可以获得超越传统雷达系统衍射极限的成像分辨能力。\n这段文字无法解释下列哪一问题?",
