   "question": "面对新的形势和要求，必须进一步全面深化改革，继续完善各方面制度机制，因而制度建设的任务更为繁重艰巨，加强顶层设计更为重要。如果不能全景式俯瞰和把握制度建设全局，采取总体构想和战略谋划，做到胸中有数，            地层层系统设计，难免顾此失彼、            ，无法取得制度建设的成效。\n依次填入画横线部分最恰当的一项是：",
