   "source": "2026年国家公务员录用考试《行测》题（副省级） · 第22题",
   "question": "埋藏较浅的饱水松散砂土遭受地震等强烈振动时，颗粒间的位置迅速调整，相互间失去接触压力和摩擦力，有被振密的趋势。由于孔隙水压力急剧升高，颗粒快速聚集、挤出，随着水流不断翻滚，由固态砂土变成液态混合物，这个过程叫作“液化”。液态混合物会向压力低的方向运动，若地下有合适的通道或洞穴，则会涌向这些地方。当它们涌出地表，呈现喷砂冒水状态时，就被称为“砂涌”。它们在流动过程中会破坏沿途的地貌景观和建筑，严重时还会造成人畜伤亡。\n这段文字所描述的自然现象可以概括为：",
   "options": [
    "A. 潜藏在地下的“暗河”",
    "B. 被摇成“液体”的砂土",
    "C. 沙漠中的“隐形”杀手",
    "D. 大地的“多米诺骨牌”效应"
   ],
   "answer": "B",
   "analysis": "文段开篇介绍埋藏较浅的饱水松散砂土在遭受地震等强烈振动时，颗粒间位置调整，由于孔隙水压力升高，固态砂土会变成液态混合物，即“液化”，接着说明液态混合物会向压力低的方向运动，涌出地表形成“砂涌”，最后阐述其在流动过程中的危害。故文段围绕的核心话题为“砂土”，重点介绍了砂土在特定条件下变成液态混合物及形成砂涌的现象，对应B项。\nA项，“暗河”表述不明确，未提及文段主题词“砂土”，排除；\nC项，“沙漠”无中生有，且未提及文段主题词“砂土”，排除；\nD项，“多米诺骨牌”效应指系统中微小初始能量引发系列连锁变化，无中生有，且未提及文段主题词“砂土”，排除。\n故正确答案为B。\n【文段出处】知识就是力量2024年05期《砂土液化》",
