   "question": "既往研究发现，病理性img/formula-6e27632bdd146bdd.webp-突触核蛋白是帕金森病的关键致病蛋白。在病理条件下，正常的img/formula-6e27632bdd146bdd.webp-突触核蛋白单体会发生错误折叠，并聚集在一起形成纤维，破坏神经元的正常功能并导致其死亡。它还会像种子一样散播，入侵邻近的正常神经元，诱导更多脑区中的img/formula-6e27632bdd146bdd.webp-突触核蛋白聚集和神经元死亡，致病蛋白传播到中脑黑质区域时，可导致多巴胺能神经元死亡，从而出现动作迟缓、静止性震颤、肌强直等运动症状；传播到大脑皮层时，则会出现记忆力下降等认知障碍症状。\n这段文字接下来最可能讲的是：",
