   "source": "2026年国家公务员录用考试《行测》题（副省级） · 第25题",
   "question": "①在这种条件下点火并稳定燃烧，好比在12级狂风中点燃一根火柴\n②在高超声速飞行器穿越云霄的征途中，动力推进技术就是打开高速大门的金钥匙\n③当燃烧室内气流流速超过声速时，会形成复杂的激波系，激波前后气流状态会产生突变\n④目前，超燃冲压发动机是这一领域的明星，它可以在大气中有效获取氧气，并且在高超声速条件下稳定燃烧\n⑤想象一下，让一个重达数吨的飞行器在空气稀薄的高空中以数倍声速疾驰，需要多么强大的发动机提供足够的推力\n⑥此时，常规的发动机技术完全不能适用，只有超燃冲压发动机才能在极短时间内将大量燃料转化为推力，并让飞行器加速稳定在高超声速\n将以上6个句子重新排列，语序正确的一项是：",
   "options": [
    "A. ②⑥③①④⑤",
    "B. ②⑤④③①⑥",
    "C. ⑤④①⑥③②",
    "D. ⑤③②④⑥①"
   ],
   "answer": "B",
   "analysis": "观察选项，对比首句。②句引入“高超声速飞行器”这一话题并指出动力推进技术是高超声速飞行器的关键，⑤句指出飞行器在高空中高速疾驰的过程中，对发动机推力的严苛要求，根据行文逻辑，应先引出高超声速飞行器这一话题，强调动力推进技术的重要性之后，再以“想象一下”引导一个具体的场景对②句中的观点进行论证，故②句应在⑤句之前，排除C、D两项。\n分析A、B两项，对比尾句。⑤句指出飞行器在高空中高速疾驰的过程中，对发动机推力的严苛要求，⑥句通过对比常规发动机与超燃冲压发动机，指出超燃冲压发动机在高超声速条件下的不可替代性，根据行文逻辑，应先提出对发动机推力的严苛要求，再总结超燃冲压发动机在高超声速条件下的不可替代性，故⑤句应在⑥句之前，排除A项。\n故正确答案为B。\n【文段出处】中国军网-解放军报《高超声速飞行器：穿越云霄的“极速传奇”》",
   "exam": "guokao",
   "year": 2026,
   "materialId": "xzm-9ub4se-2"
