   "source": "2026年国家公务员录用考试《行测》题（副省级） · 第27题",
   "question": "行政决策要遵循科学、民主和依法的原则，但                    。按照行政决策的性质及目标划分，行政决策可分为经营性决策和管理型决策。经营性决策是政府为履行发展职能，促进经济社会发展而实施的决策，如制定产业政策、作出招商引资决定等，涉及经济社会高质量发展，因而需要更多遵循经济规律，面向市场进行成本效益分析，量力而行。管理型决策则是直接涉及行政相对人的利益，如公共福利政策制定、生态环境保护措施等，需要更多的开放性和公众参与。凡是利益相关者，都应赋予其表达意见、参与决策的权利。\n填入画横线部分最恰当的一项是：",
   "options": [
    "A. 要注意倾听各利益相关群体的不同声音",
    "B. 应根据现实中的具体情况进行适当调整",
    "C. 仍然需要完善相关制度以确保其规范运行",
    "D. 具体要求则因行政决策性质的不同而有差异"
   ],
   "answer": "D",
   "analysis": "横线出现在文段开头，且为首句中的分句，需结合首句及后文内容分析。文段开篇指出行政决策要遵循的原则，横线后指出按照行政决策的性质及目标，将其分为经营性决策和管理型决策。后文针对经营性决策和管理型决策的区别详细介绍。故文段强调了行政决策需要根据性质及目标不同，采取不同的行政决策模式，对应D项。\nA项，仅对应后文“管理型决策”的相关内容，表述片面，排除；\nB项，“具体情况”表述笼统，且缺少核心话题“行政决策”，排除；\nC项，“完善相关制度以确保其规范运行”文段并未涉及相关内容，无法与后文衔接，排除。\n故正确答案为D。\n【文段出处】民主与法制网《完善行政决策制度体系 提升行政决策质量和效率》",
   "exam": "guokao",
   "year": 2026,
   "materialId": "xzm-9ub4se-2"
