   "source": "2026年国家公务员录用考试《行测》题（副省级） · 第28题",
   "question": "在信息技术领域，晶体管和激光器是两大核心元件。晶体管的微型化推动电子芯片飞速发展，催生摩尔定律，即每隔约18个月，集成电路上可容纳的晶体管数量将翻一番，这一趋势推动最先进的晶体管尺寸达到纳米级别。相比晶体管，缩小激光器的难度要大得多，因为两者所依赖的微观粒子截然不同，前者依赖电子，后者依赖光子。在可见光和近红外波段，光子波长比晶体管中的电子波长高出3个数量级。受衍射极限制约，这些光子能被压缩到的最小模式体积比晶体管中的电子要大10亿倍。因此，构建纳米尺度激光器的核心挑战在于如何突破衍射极限，将光子的体积“压缩”到最小。\n这段文字主要介绍：",
   "options": [
    "A. 构建纳米尺度激光器的难点",
    "B. 信息技术领域面临的核心挑战",
    "C. 摩尔定律对于突破衍射极限的制约",
    "D. 晶体管微型化对电子芯片发展的意义"
   ],
   "answer": "A",
   "analysis": "文段开篇介绍信息技术领域的两大核心元件，即晶体管和激光器。随后说明晶体管的微型化推动最先进的晶体管尺寸达到纳米级别，接着通过对比指出，激光器缩小难度比晶体管更大，并分析其物理原因——光子波长数量级较高，受衍射极限限制，最小模式体积远大于电子，最后通过“因此”总结，强调构建纳米尺度激光器的核心挑战在于突破衍射极限、压缩光子体积。故文段重点在于分析构建纳米尺度激光器的难点，对应A项。\nB项，“信息技术领域”范围过大，文段聚焦构建纳米尺度激光器问题，排除；\nC项，“摩尔定律对于突破衍射极限的制约”文段并未提及，无中生有，排除；\nD项，“晶体管微型化对电子芯片发展的意义”仅对应文段的引入铺垫部分，非重点，排除。\n故正确答案为A。\n【文段出处】光明日报《纳米激光器：“小”到极致的光》",
   "exam": "guokao",
   "year": 2026,
   "materialId": "xzm-9ub4se-2"
