   "question": "五彩滩是一处著名的雅丹地貌景观，位于新疆维吾尔自治区，中国唯一一条注入北冰洋的河流额尔齐斯河穿其而过。南岸有绿洲、沙漠，北岸则是            的泥岩、砂岩及砂砾组成的奇石怪岩，这两种            的地貌遥相辉映，“一河隔两岸，胜似两重天”。\n依次填入画横线部分最恰当的一项是：",
