   "source": "2026年国家公务员录用考试《行测》题（地市级） · 第30题",
   "question": "。太阳系中的小行星数不胜数，它们是太阳系形成后遗留的残余碎片，仅在地球轨道周围就运行着数以千万计的小行星，它们与地球一样环绕太阳运行。当这些小行星与地球轨道发生交会时，如果其轨道能量与地球相近，它们就可能被地球引力捕获，成为地球的“迷你月亮”。根据科学家推断，地球周围随时都可能有“迷你月亮”在运行，只是目前人类观测能力有限，无法定位其具体位置。\n填入画横线部分最恰当的一项是：",
