   "question": "把握好动静之度，是解决问题的关键。过度求静易陷入消极懈怠、            的泥潭。在面对新问题时，往往会因为害怕承担责任或者担心打破现有秩序，一味地观望等待，致使问题越积越多。相反，情况不明时过于求动会让很多事情变得杂乱无章，往往            。\n依次填入画横线部分最恰当的一项是：",
